-- Approved Cube / Haki staging helpers. No formal G dispatch or migration is installed here.
create or replace function ml_private.p3g_cube_move(s jsonb,cmd jsonb) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$declare a integer:=(cmd->>'actor')::int;cost integer;used integer;begin
 perform ml_private.need(s#>>array['players',a::text,'moved']<>'true' and coalesce(s#>>array['stage3','c','blocked',a::text],'false')<>'true','本个人回合已使用基础移动');perform ml_private.need(not ml_private.stage3_mount_blocked(s,a),'小白马：有坐骑者暂时不能主动位移');cost:=case when ml_private.stage3_equipped(s,a,'basic-071') then 0 else ml_private.stage3_fixed_cost(s,a,ml_private.stage4_location_move_cost(s,a)) end;perform ml_private.need((s#>>array['players',a::text,'ap'])::int>=cost,'移动需要1AP');perform ml_private.need(jsonb_typeof(cmd->'cell')='string' and ml_private.p3g_cube_cells(s,a) ? (cmd->>'cell'),'魔方传送请选择全图合法空格');s:=ml_private.p3d_pay(s,a,cost);used:=(s#>>array['stage3','basicUsed',a::text])::int+1;s:=jsonb_set(s,array['stage3','basicUsed',a::text],to_jsonb(used));s:=jsonb_set(s,array['players',a::text,'moved'],to_jsonb(used>=case when s#>>array['stage3','doubleMove',a::text]='true' then 2 else 1 end));s:=ml_private.stage3_relocate(s,a,cmd->>'cell',true);s:=jsonb_set(s,'{queue}',(s->'queue')||(s->'_relocationTasks'))-'_relocationTasks';return ml_private.emit(s,'cost','S'||(a+1)||' 魔方基础传送支付'||cost||'AP，不掷移动骰');end $$;
create or replace function ml_private.p3g_cube_face(s jsonb,a integer) returns integer language sql immutable set search_path=pg_catalog,ml_private as $$select case when ml_private.p3g_enabled(s) and (s->>'active')::int=a and s#>>array['players',a::text,'character']='character-028' then coalesce((s#>>array['stage3','g','face',a::text])::int,0) else 0 end$$;
create or replace function ml_private.p3g_cube_draw(s jsonb,a integer) returns integer language sql immutable set search_path=pg_catalog,ml_private as $$select case when ml_private.p3g_cube_face(s,a)=3 and coalesce(s#>>array['stage4','drawBlocked',a::text],'false')<>'true' then 2 else 0 end$$;
create or replace function ml_private.p3g_cube_start_tasks(s jsonb,a integer) returns jsonb language sql immutable set search_path=pg_catalog,ml_private as $$select case when ml_private.p3g_enabled(s) and (s#>>array['players',a::text,'hp'])::int>0 and s#>>array['players',a::text,'character']='character-028' then jsonb_build_array(ml_private.stage3_task('g-cube-start',jsonb_build_object('actor',a))) else '[]'::jsonb end$$;
create or replace function ml_private.p3g_cube_cells(s jsonb,a integer) returns jsonb language sql stable set search_path=pg_catalog,ml_private as $$select coalesce(jsonb_agg(c->'id' order by n),'[]') from jsonb_array_elements(ml_private.game_data(s,'cells')) with ordinality q(c,n) where ml_private.p3g_cube_face(s,a)=6 and s#>>array['players',a::text,'moved']<>'true' and not ml_private.stage3_mount_blocked(s,a) and c->>'id'<>s#>>array['players',a::text,'cell'] and ml_private.stage4_board_empty(s,a,c->>'id',jsonb_build_array(a))$$;
create or replace function ml_private.p3g_cube_boost(s jsonb,h jsonb) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$declare target integer:=(h->>'target')::int;owner integer:=(s#>>array['stage3','g','marks',target::text])::int;begin
 if ml_private.p3g_enabled(s) and (h->>'amount')::int>0 and owner is not null and ml_private.character_effect_allowed(jsonb_build_object('origin','role-locked','actor',owner,'roleModifiers','[]'::jsonb),target,s#>>array['players',target::text,'character']) then s:=jsonb_set(s,array['stage3','g','marks',target::text],'null');s:=ml_private.emit(s,'skill','S'||(target+1)||' 消耗S'||(owner+1)||'魔方标记，本份伤害＋1');h:=h||jsonb_build_object('amount',(h->>'amount')::int+1);end if;return s||jsonb_build_object('_hit',h);end $$;
create or replace function ml_private.p3g_cube_injury(s jsonb,h jsonb,loss integer) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$declare target integer:=(h->>'target')::int;src integer:=(h->>'source')::int;begin
 if ml_private.p3g_enabled(s) and loss>0 and src is not null and ml_private.p3g_cube_face(s,src)=5 and ml_private.stage4_on_board(s,target) and ml_private.character_effect_allowed(jsonb_build_object('origin','role-locked','actor',src,'roleModifiers','[]'::jsonb),target,s#>>array['players',target::text,'character']) then s:=jsonb_set(s,array['stage3','g','marks',target::text],to_jsonb(src));s:=ml_private.emit(s,'skill','S'||(target+1)||' 获得S'||(src+1)||'魔方标记');end if;return s;end $$;
create or replace function ml_private.p3g_cube_task(s jsonb,t jsonb,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$declare a integer:=(t->>'actor')::int;roll integer;gain jsonb;begin
 if not ml_private.p3g_enabled(s) or t->>'action'<>'g-cube-start' then return s||jsonb_build_object('_gCubeHandled',false);end if;
 if (s#>>array['players',a::text,'hp'])::int>0 and s#>>array['players',a::text,'character']='character-028' then s:=ml_private.p3g_die(s,'魔法有方',a);roll:=(s->>'_roll')::int;s:=s-'_roll';s:=jsonb_set(s,array['stage3','g','face',a::text],to_jsonb(roll));s:=ml_private.emit(s,'skill','S'||(a+1)||' 魔法有方：本个人回合采用'||roll);if roll=4 then s:=ml_private.stage3_gain_ap(s,a,2);gain:=s->'_gain';s:=s-'_gain';s:=ml_private.emit(s,'ap','S'||(a+1)||' 魔法有方额外获得'||(gain->>'gained')||'AP，晓虫收取'||(gain->>'taken')||'AP');end if;end if;return s||jsonb_build_object('_gCubeHandled',true);end $$;
create or replace function ml_private.p3g_haki(s jsonb,a integer) returns boolean language sql immutable set search_path=pg_catalog,ml_private as $$select ml_private.p3g_enabled(s) and (s->>'active')::int=a and s#>>array['players',a::text,'character']='character-049' and coalesce(s->'movement' ? 'haki',false)$$;
create or replace function ml_private.p3g_haki_crossed(s jsonb,a integer,origin text,destination text) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$declare map jsonb:=ml_private.game_data(s,'map');startc jsonb:=map->origin;endc jsonb:=map->destination;dr integer:=sign((endc->>'row')::int-(startc->>'row')::int);dc integer:=sign((endc->>'col')::int-(startc->>'col')::int);cell text;i integer;q jsonb;target integer;jobs jsonb:='[]';begin
 if ml_private.p3g_haki(s,a) then for i in 1..ml_private.distance_for_version(s->>'version',origin,destination) loop cell:='r'||((startc->>'row')::int+dr*i)||'c'||((startc->>'col')::int+dc*i);for q in select * from ml_private.arr(s->'players') loop target:=(q->>'seat')::int;if target<>a and ml_private.stage4_on_board(s,target) and q->>'cell'=cell and not(s#>'{movement,haki}' @> jsonb_build_array(target)) then s:=jsonb_set(s,'{movement,haki}',(s#>'{movement,haki}')||jsonb_build_array(target));jobs:=jobs||jsonb_build_array(ml_private.stage3_task('g-haki',jsonb_build_object('actor',a,'target',target)));end if;end loop;end loop;end if;return s||jsonb_build_object('_gHakiTasks',jobs);end $$;
create or replace function ml_private.p3g_haki_task(s jsonb,t jsonb,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$declare a integer:=(t->>'actor')::int;target integer:=(t->>'target')::int;begin
 if not ml_private.p3g_enabled(s) or t->>'action'<>'g-haki' then return s||jsonb_build_object('_gHakiHandled',false);end if;if ml_private.p3g_haki(s,a) and ml_private.stage4_on_board(s,a) and ml_private.p3f_allowed(s,a,target) then s:=ml_private.select_choice(s,'g-haki',a,at,jsonb_build_object('source',target));end if;return s||jsonb_build_object('_gHakiHandled',true);end $$;
create or replace function ml_private.p3g_haki_choose(s jsonb,cmd jsonb,at double precision,timeout boolean) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$declare a integer:=(s#>>'{choice,actor}')::int;target integer:=(s#>>'{choice,source}')::int;begin
 if not ml_private.p3g_enabled(s) or s#>>'{choice,kind}'<>'g-haki' then return s||jsonb_build_object('_gHakiHandled',false);end if;if not timeout and cmd->>'accept'='true' and ml_private.p3g_haki(s,a) and ml_private.stage4_on_board(s,a) and ml_private.p3f_allowed(s,a,target) then s:=ml_private.p3f_damage(s,jsonb_build_array(jsonb_build_object('source',a,'target',target,'amount',1,'category','response')),false,false);s:=ml_private.stage3_prepend(s,s->'_triggers')-'_triggers';end if;return s||jsonb_build_object('_gHakiHandled',true);end $$;
